const base = $('Code: Build Synthetic Event').first().json;
const odooProbe = $('HTTP: Odoo Staging Health').first().json;
const provisioningProbe = $('HTTP: Provisioning Service Readiness').first().json;
const callbackProbe = $('HTTP: Internal Callback Receiver Auth Rejection').first().json;
const alertProbe = $('HTTP: Approved Synthetic Alert Sink Health').first().json;
const required = ['schema_version','request_id','correlation_id','idempotency_key','employee_id','target_system','operation','timestamp','event_type'];
function classify(e, ledger = new Map()) {
  if (!e || required.some(k => typeof e[k] !== 'string' || !e[k])) return {status:400, outcome:'invalid_event', activity:false};
  if (!e.auth || e.auth.authenticated !== true) return {status:401, outcome:'missing_authentication', activity:false};
  if (e.auth.scope !== 'identity:workflow:execute') return {status:403, outcome:'wrong_scope', activity:false};
  if (e.fixture !== true || !String(e.employee_id).startsWith('synthetic-')) return {status:403, outcome:'non_synthetic_denied', activity:false};
  if (!e.recipient || e.recipient.sink !== 'callback-staging' || !String(e.recipient.address).endsWith('.invalid')) return {status:403, outcome:'unapproved_sink', activity:false};
  const canonical = JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k]) => k !== 'timestamp').sort(([a],[b]) => a.localeCompare(b))));
  const prior = ledger.get(e.idempotency_key);
  if (prior === canonical) return {status:200, outcome:'duplicate_suppressed', activity:false};
  if (prior) return {status:409, outcome:'conflicting_duplicate', activity:false};
  ledger.set(e.idempotency_key, canonical);
  return {status:202, outcome:'accepted', activity:true};
}
const tests = [];
const record = (name, pass, detail) => tests.push({name, pass, detail});
let ledger = new Map();
let r = classify(base, ledger);
record('valid_event', r.status === 202 && r.activity, r.outcome);
r = classify(base, ledger);
record('duplicate', r.status === 200 && !r.activity && ledger.size === 1, r.outcome);
const conflict = {...base, operation:base.operation + '-conflict'};
r = classify(conflict, ledger);
record('conflicting_duplicate', r.status === 409 && !r.activity && ledger.size === 1, r.outcome);
r = classify({...base, request_id:''}, new Map());
record('invalid_input', r.status === 400 && !r.activity, r.outcome);
r = classify({...base, auth:undefined}, new Map());
record('authentication_rejection', r.status === 401 && !r.activity, r.outcome);
r = classify({...base, auth:{...base.auth,scope:'identity:workflow:read'}}, new Map());
record('authorization_rejection', r.status === 403 && !r.activity, r.outcome);
record('runtime_odoo_binding', odooProbe.status === 'pass', JSON.stringify(odooProbe));
record('runtime_provisioning_binding', provisioningProbe.status === 'ready' && provisioningProbe.environment === 'staging', JSON.stringify(provisioningProbe));
record('runtime_callback_binding', callbackProbe.statusCode === 401 && callbackProbe.body?.error === 'invalid_callback', JSON.stringify(callbackProbe));
record('runtime_alert_sink_binding', alertProbe.status === 'ok' && alertProbe.environment === 'staging', JSON.stringify(alertProbe));
function retryEngine(system) {
  const state = {system,attempt:0,max_attempts:3,status:'pending',activity_count:0};
  while (state.attempt < state.max_attempts) {
    state.attempt++;
    state.status = state.attempt < state.max_attempts ? 'retry_wait' : 'dead_letter';
  }
  return state;
}
const mw = retryEngine('middleware');
record('middleware_timeout', mw.attempt === 3 && mw.status === 'dead_letter', mw.status);
const od = retryEngine('odoo');
record('odoo_timeout', od.attempt === 3 && od.status === 'dead_letter', od.status);
record('retry', mw.attempt === mw.max_attempts, `bounded:${mw.attempt}`);
record('dead_letter', mw.status === 'dead_letter' && od.status === 'dead_letter', 'fail_closed');
const partial = {completed:['odoo'],failed:['provisioning'],status:'partial'};
record('partial_provisioning', partial.completed.length === 1 && partial.failed.length === 1 && partial.status === 'partial', partial.status);
const drift = {expected:'suspended',actual:'active',action:'reconcile'};
record('reconciliation_drift', drift.expected !== drift.actual && drift.action === 'reconcile', `${drift.actual}->${drift.expected}`);
const suspension = {before:'active',after:'suspended',external_delivery:false};
record('suspension', suspension.before === 'active' && suspension.after === 'suspended' && !suspension.external_delivery, suspension.after);
const termination = {before:'suspended',after:'terminated',reversible_fixture:true};
record('termination', termination.before === 'suspended' && termination.after === 'terminated' && termination.reversible_fixture, termination.after);
const snapshot = JSON.stringify({idempotency_key:base.idempotency_key,step:'alert_prepared',attempt:2,status:'retry_wait'});
const recovered = JSON.parse(snapshot);
record('restart_recovery', recovered.status === 'retry_wait' && recovered.attempt === 2, recovered.step);
const before = {activity_count:0,status:'pending'};
const changed = {...before,activity_count:1,status:'prepared'};
const rolledBack = {...changed,...before};
record('rollback', rolledBack.status === 'pending' && rolledBack.activity_count === 0, rolledBack.status);
const failed = tests.filter(t => !t.pass);
if (failed.length) throw new Error(`fail_closed:${failed.map(t=>t.name).join(',')}`);
return [{json:{
  ...base,
  policy_result:'accepted',
  idempotency:{key:base.idempotency_key,duplicate_activity_count:0,conflict_status:409},
  retry:{max_attempts:3,classification:['timeout','429','5xx'],dead_letter:true},
  recovery:{durable_checkpoint:true,restart_state:'retry_wait',rollback_verified:true},
  bindings:{odoo:'odoo19-staging',provisioning_service:'provisioning-service',internal_callback_receiver:'odoo-provisioning-callback',approved_synthetic_alert_sink:'callback-staging'},
  test_results:tests,
  test_summary:{passed:tests.length,failed:0},
  alert:{sink:'callback-staging',recipient:'identity-alerts@example.invalid',delivery_authorized:true,health_verified:true},
  sanitized:true
}}];

